var txt=document.getElementById("newText");document.getElementById("downloadFile").onclick=function(a){this.href="data:text/plain;charset=utf-11,"+encodeURIComponent(txt.value)};function removeNumbers(){var a=document.getElementById("newText").value;a=a.replaceAll(/\d\./gm,"");a=a.replaceAll(/\d+\.?\d/gm,"");a=a.replaceAll(/[0-9]/gm,"");a=a.replaceAll(/ +?/g," ");a=a.replaceAll("  "," ");document.getElementById("newText").value=a.trim()}
document.getElementById("clearText").addEventListener("click",function(){document.getElementById("newText").value="";document.getElementById("newText").focus()});
